    "\nSELECT\n    o.id AS id,\n    o.order_ref_no AS order_ref_no,\n    o.created_at AS transaction_date,\n    s.location_code AS LocationCode,\n    CASE\n        WHEN\n            o.payment_method = 14 AND (ptt.id IS NULL AND ppt.id IS NULL)\n                AND oss.offline_payment > 0\n                AND oss.online_other_payment = 0\n        THEN\n            'POC(Cash)'\n        WHEN\n        o.payment_method = 14 AND (ptt.id IS NULL AND ppt.id IS NULL AND oss.credit_pincode_id IS NOT NULL AND oss.credit_pincode_id != '')\n            AND oss.offline_payment = 0\n            AND oss.online_other_payment > 0\n        THEN\n            'Pincode'\n        WHEN\n        o.payment_method = 14 AND (ptt.id IS NULL AND ppt.id IS NULL AND oss.district_transaction_id IS NOT NULL AND oss.district_transaction_id != '')\n            AND oss.offline_payment = 0\n            AND oss.online_other_payment > 0\n        THEN\n            'District'\n        WHEN\n            o.payment_method = 14 AND (ptt.id IS NULL AND ppt.id IS NULL)\n                AND oss.offline_payment = 0\n                AND oss.online_other_payment > 0\n        THEN\n            'POC(Online Others)'\n        WHEN\n            o.payment_method = 14 AND (ptt.id IS NULL AND ppt.id IS NULL)\n                AND oss.offline_payment > 0\n                AND oss.online_other_payment > 0\n        THEN\n            'POC(Cash + Online Others)'\n        WHEN\n            o.payment_method = 14\n                AND ( ptt.cash_amount > 0 OR ppt.cash_amount > 0 )\n        THEN\n            CONCAT('POC(Cash + ', ptpm.name, ')')\n        WHEN\n            o.payment_method = 14\n                AND ( ptt.cash_amount = 0 OR ppt.cash_amount = 0 )\n        THEN\n            CONCAT('POC(', ptpm.name, ')')\n        WHEN\n            o.payment_method = 3\n        THEN\n            CONCAT('Prepaid(', pm.name, ')')\n        WHEN\n            o.payment_method = 15\n        THEN\n            'Shopify'\n        ELSE 'Payment Not Done'\n    END AS PaymentMode,\n    o.pay_amt AS PayAmount,\n    oss.offline_payment AS CASH,\n    ptt.amount AS PinelabCardUpi,\n    ppt.amount AS PaytmCardUpi,\n    CASE\n        WHEN oss.district_transaction_id IS NOT NULL AND oss.district_transaction_id != '' THEN oss.online_other_payment\n        ELSE 0\n    END AS DistrictAmount,\n    CASE\n        WHEN oss.credit_pincode_id IS NOT NULL AND oss.credit_pincode_id != '' THEN oss.online_other_payment\n        ELSE 0\n    END AS CreditPincodeAmount,\n    CASE\n        WHEN (oss.district_transaction_id IS NULL OR oss.district_transaction_id = '')\n             AND (oss.credit_pincode_id IS NULL OR oss.credit_pincode_id = '')\n        THEN oss.online_other_payment\n        ELSE 0\n    END AS OnlineOther,\n    o.tss_money_used AS TssMoneyUsed,\n    o.tss_points_used AS TssPointsUsed,\n    o.coupon_amt_used AS CouponAmountUsed,\n    o.voucher_amt_used AS VoucherAmountUsed,\n    o.pg_disc AS PgDisc,\n    o.order_amt AS OrderAmount,\n    ps.payment_status AS PaymentStatus,\n    sc.counter_name AS counter_name,\n    hp.gst AS TaxRate,\n    CASE\n        WHEN o.created_at >= '2026-03-27 00:00:00' THEN\n            hp.pre_gst_amt\n        WHEN o.id >= 17146133 AND hp.hp_tss_points_used > 0 AND (hp.store_disc_pg > 0 or hp.disc > 0) THEN\n            ROUND(\n                (hp.price-hp.store_disc_pg-hp.disc) / (1 + hp.gst / 100.0) - (\n                o.tss_points_used /\n                (SELECT SUM(hpp.price / (1 + hpp.gst / 100))\n                 FROM has_products hpp\n                 WHERE hpp.order_id = o.id)\n            ) * (hp.price / (1 + hp.gst / 100)),\n            2)\n        WHEN o.id >= 17146133 AND hp.hp_tss_points_used > 0 AND (hp.store_disc_pg <= 0 or hp.disc <= 0) THEN\n            ROUND(\n                (\n                    hp.price / (1 + hp.gst / 100.0)\n                )\n                -\n                (\n                    o.tss_points_used\n                    *\n                    (hp.price / (1 + hp.gst / 100.0))\n                    /\n                    NULLIF(\n                        (\n                            SELECT SUM(hpp.price / (1 + hpp.gst / 100.0))\n                            FROM has_products hpp\n                            WHERE hpp.order_id = o.id\n                        ),\n                        0\n                    )\n                ),\n            2)\n        WHEN o.id >= 17146133 AND (hp.store_disc_pg > 0 or hp.disc > 0) THEN\n            ROUND((hp.price - hp.disc - hp.store_disc_pg) / (1 + (hp.gst / 100)), 2)\n        WHEN hp.hp_tss_points_used > 0 THEN\n            ROUND(\n                (hp.price - hp.hp_tss_points_used) /\n                (1 + (hp.gst / 100)),\n            2)\n        WHEN hp.disc > 0 THEN\n            ROUND(\n                (hp.price - hp.disc) /\n                (1 + (hp.gst / 100)),\n            2)\n        ELSE\n            ROUND(\n                (hp.price) /\n                (1 + (hp.gst / 100)),\n            2)\n    END AS LineItemSubTotalWoTax,\n    MAX(CASE\n        WHEN hp.return_mode = 5 AND hp.status = 'EXCHANGE_COMPLETED' THEN tmh.added_amt\n        ELSE arl.refunded_amt\n    END) AS PayAmountRefunded,\n    CASE\n        WHEN hp.return_mode = 5 AND hp.status = 'EXCHANGE_COMPLETED' THEN 'TSS_MONEY'\n        ELSE arl.refund_mode\n    END AS PayAmountRefundedMode\nFROM\n    orders o\n        JOIN\n    has_products hp ON o.id = hp.order_id\n        LEFT JOIN\n    amount_to_be_refunded_log arl ON arl.order_id = hp.order_id\n            AND arl.prod_id = hp.prod_id\n            AND arl.has_product_id = hp.id\n        LEFT JOIN\n    tss_money_history tmh ON tmh.order_id = o.id AND tmh.has_product_id = hp.id\n            AND tmh.platform = 'EXCHANGE' AND tmh.added_amt > 0\n        LEFT JOIN\n    users u ON o.user_id = u.id\n        LEFT JOIN\n    payment_method pm ON o.payment_method = pm.id\n        LEFT JOIN\n    payment_status ps ON o.payment_status = ps.id\n        LEFT JOIN\n    order_stores oss ON o.id = oss.order_id\n        LEFT JOIN\n    stores s ON oss.store_id = s.id\n        LEFT JOIN\n    pos_terminal_transactions ptt ON (o.id = ptt.order_id AND ptt.is_active = 1)\n        AND ptt.platform = 'txn_completed'\n        LEFT JOIN\n    pos_paytm_transactions ppt ON (o.id = ppt.order_id AND ppt.is_active = 1)\n        AND ppt.platform = 'txn_completed'\n        LEFT JOIN\n    pos_terminal_payment_modes ptpm ON (ptt.payment_mode = ptpm.mode_id OR ppt.payment_mode = ptpm.mode_id)\n        LEFT JOIN\n    store_counters sc ON sc.id = oss.counter_id\nWHERE\n    o.order_status NOT IN (0 , 17)\n        AND oss.id IS NOT NULL\n        AND u.email NOT IN ('algoshack.tss@gmail.com' , 'schedular.tss@gmail.com', 'schedular.wwe@gmail.com','algoshack.wweshop@gmail.com')",
